for fn,b in [('shallow','/app/output/revealed_canvas.png'),('deep','/app/output/revealed2_canvas.png')]:
 a=np.array(Image.open(b)).astype(float)
 for name,(x0,x1,y0,y1) in [('shallow',(370,510,175,225)),('deep',(500,630,125,190))]:
  if (name=='shallow')!=(fn=='shallow'): continue
  roi=a[y0:y1,x0:x1]
  bg=np.array([224,221,213.]); d=np.linalg.norm(roi-bg,axis=2)
  for th in [10,20,40]:
   y,x=np.where(d>th)
